{
  "findings": [
    {
      "check_id": "CKV2_AZURE_31",
      "title": "Subnet is not associated with a Network Security Group",
      "resource": "azurerm_subnet.private_subnet",
      "severity": "MEDIUM",
      "explanation": "The subnet has no associated Network Security Group, leaving subnet traffic without an explicit network-layer access control boundary. Associating an NSG provides default deny behavior for unsolicited inbound traffic and enables controlled rule enforcement."
    }
  ],
  "patched_code": "resource "azurerm_subnet" "private_subnet" {
  name                 = "smart-manufacturing-iot-monitoring-platform-subnet-private"
  resource_group_name  = azurerm_resource_group.smart_manufacturing.name
  virtual_network_name = azurerm_virtual_network.smart_manufacturing_vnet.name
  address_prefixes     = ["10.0.2.0/24"]
}

resource "azurerm_network_security_group" "private_subnet" {
  name                = "smart-manufacturing-iot-monitoring-platform-subnet-private-nsg"
  location            = azurerm_resource_group.smart_manufacturing.location
  resource_group_name = azurerm_resource_group.smart_manufacturing.name
}

resource "azurerm_subnet_network_security_group_association" "private_subnet" {
  subnet_id                 = azurerm_subnet.private_subnet.id
  network_security_group_id = azurerm_network_security_group.private_subnet.id
}
",
  "fix_summary": "Added a Network Security Group and associated it with the private subnet. The NSG's default rules deny unsolicited inbound traffic while preserving Azure's standard virtual-network and load-balancer allowances."
}
